sys_variable_value.value:
(function execute(inputs, outputs) {


var convertidoArray = JSON.parse(inputs.objeto);
gs.info('PK - luc_atual_v2 PKPKPK')

for (var i = 0; i < convertidoArray.length; i++) {
    var lucAtualV2 = convertidoArray[i].luc_atual_v2; 
    gs.info("PK - luc_atual_v2[" + i + "]: " + lucAtualV2); 
}
outputs.lucatual = lucAtualV2;
})(inputs, outputs);

